package com.trimtime.barber;
import com.trimtime.catalogue.*; import com.trimtime.salon.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class BarberQualificationService { private final SalonRepository salons; private final BarberMembershipRepository memberships; private final BarberServiceQualificationRepository qualifications; private final ServiceOfferingRepository services; public BarberQualificationService(SalonRepository salons,BarberMembershipRepository memberships,BarberServiceQualificationRepository qualifications,ServiceOfferingRepository services){this.salons=salons;this.memberships=memberships;this.qualifications=qualifications;this.services=services;}
 @Transactional(readOnly=true) public List<BarberQualificationDtos.BarberResponse> list(Long ownerId){var salon=salons.findByOwnerId(ownerId).orElseThrow(SalonMissingException::new);return memberships.findBySalonId(salon.getId()).stream().map(m->response(m.getBarber().getId(),m.getBarber().getDisplayName())).toList();}
 @Transactional public BarberQualificationDtos.BarberResponse update(Long ownerId,Long barberId,BarberQualificationDtos.UpdateRequest input){var salon=salons.findByOwnerId(ownerId).orElseThrow(SalonMissingException::new);var membership=memberships.findByBarberId(barberId).filter(m->m.getSalon().getId().equals(salon.getId())).orElseThrow(BarberMissingException::new);var selected=input.serviceIds().stream().distinct().map(id->services.findByIdAndSalonId(id,salon.getId()).filter(ServiceOffering::isActive).orElseThrow(ServiceMissingException::new)).toList();qualifications.deleteByBarberId(barberId);qualifications.flush();qualifications.saveAll(selected.stream().map(s->new BarberServiceQualification(membership.getBarber(),s)).toList());return response(barberId,membership.getBarber().getDisplayName());}
 private BarberQualificationDtos.BarberResponse response(Long id,String name){return new BarberQualificationDtos.BarberResponse(id,name,qualifications.findByBarberId(id).stream().map(q->q.getService().getId()).toList());}
 public static class SalonMissingException extends RuntimeException{} public static class BarberMissingException extends RuntimeException{} public static class ServiceMissingException extends RuntimeException{}
}
